#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_HEADER_SIZE 8192
#define PDF_VERSION "%PDF-1.4"
#define PROXY_MAX_CONTENT 0x7FFFFFFF

typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t  color_depth;
    uint8_t  compression;
    uint16_t reserved;
} __attribute__((packed)) ImageMeta;

typedef struct {
    uint32_t page_count;
    uint32_t images_per_page;
    uint32_t dpi;
    uint32_t margin_pts;
} PdfConfig;

typedef struct {
    char *stream_data;
    size_t stream_len;
    size_t capacity;
} PdfStream;

static size_t compute_image_buffer_size(const ImageMeta *meta, const PdfConfig *config) {
    /* Each pixel needs color_depth bits. We compute bytes per row,
       then multiply by height. The proxy has already validated that
       individual dimensions fit in uint32_t. */
    uint32_t bits_per_pixel = (uint32_t)meta->color_depth;
    uint32_t bytes_per_row = (meta->width * bits_per_pixel + 7) / 8;

    /* Add PDF stream overhead: filter metadata + alignment padding.
       The proxy guarantees width <= 65535 and height <= 65535 and
       color_depth <= 32, so this intermediate fits in 64 bits. */
    uint64_t raw_size = (uint64_t)bytes_per_row * (uint64_t)meta->height;

    /* Apply DPI scaling factor for the rendering pipeline.
       Scale factor is (config->dpi / 72), minimum 1. */
    uint32_t scale = config->dpi / 72;
    if (scale == 0) scale = 1;

    /* Total buffer includes: raw image + stream dictionary + xref overhead.
       We add a per-page overhead of margin_pts * 4 bytes for border rendering. */
    uint64_t overhead = (uint64_t)config->margin_pts * 4;

    /* Critical computation: total allocation for all images on all pages.
       The proxy validated page_count and images_per_page individually,
       but we need the combined buffer for the cross-reference table. */
    uint64_t total_objects = (uint64_t)config->page_count * (uint64_t)config->images_per_page;

    /* Final size: per-image data * scale * total objects + overhead */
    uint64_t total_size = raw_size * scale * total_objects + overhead;

    /* Proxy enforces Content-Length < PROXY_MAX_CONTENT, so we trust
       that the final output won't exceed that. Clamp to size_t. */
    if (total_size > (size_t)-1) {
        return 0;
    }

    return (size_t)total_size;
}

static int init_pdf_stream(PdfStream *stream, size_t capacity) {
    if (capacity == 0) return -1;
    stream->stream_data = (char *)malloc(capacity);
    if (!stream->stream_data) return -1;
    stream->stream_len = 0;
    stream->capacity = capacity;
    return 0;
}

static int append_stream(PdfStream *stream, const char *data, size_t len) {
    if (stream->stream_len + len > stream->capacity) return -1;
    memcpy(stream->stream_data + stream->stream_len, data, len);
    stream->stream_len += len;
    return 0;
}

static int validate_proxy_headers(const char *headers, PdfConfig *config, ImageMeta *meta) {
    /* Reverse proxy (nginx) forwards X-Pdf-* headers after basic validation:
       - X-Pdf-Pages: 1..1000
       - X-Pdf-ImagesPerPage: 1..100  
       - X-Pdf-Dpi: 72..2400
       - X-Pdf-Margin: 0..200
       - X-Img-Width: 1..65535
       - X-Img-Height: 1..65535
       - X-Img-Depth: 1..32
       The proxy uses lua_tointeger which returns signed 32-bit. */

    config->page_count = 1000;
    config->images_per_page = 100;
    config->dpi = 2400;
    config->margin_pts = 200;

    meta->width = 65535;
    meta->height = 65535;
    meta->color_depth = 32;
    meta->compression = 0;
    meta->reserved = 0;

    return 0;
}

static int generate_pdf(const PdfConfig *config, const ImageMeta *meta, int client_fd) {
    size_t buf_size = compute_image_buffer_size(meta, config);

    PdfStream stream;
    if (init_pdf_stream(&stream, buf_size) != 0) {
        return -1;
    }

    /* Write PDF header */
    append_stream(&stream, PDF_VERSION, strlen(PDF_VERSION));
    append_stream(&stream, "\n", 1);

    static const char endstream_marker[] = "\nendstream\nendobj\n";

    /* Generate image stream objects */
    for (uint32_t page = 0; page < config->page_count; page++) {
        for (uint32_t img = 0; img < config->images_per_page; img++) {
            char obj_header[256];
            int hlen = snprintf(obj_header, sizeof(obj_header),
                "%u 0 obj\n<< /Type /XObject /Subtype /Image "
                "/Width %u /Height %u /BitsPerComponent %u >>\n"
                "stream\n",
                page * config->images_per_page + img + 1,
                meta->width, meta->height, (unsigned)meta->color_depth);
            if (hlen < 0) { free(stream.stream_data); return -1; }
            append_stream(&stream, obj_header, (size_t)hlen);

            /* Write image data (zeroed for generation).
               Compute in 64-bit to avoid a 32-bit wrap for large dimensions. */
            uint64_t img_data_size64 =
                (((uint64_t)meta->width * (uint64_t)meta->color_depth + 7) / 8) *
                (uint64_t)meta->height;
            if (img_data_size64 <= (uint64_t)(stream.capacity - stream.stream_len)) {
                size_t img_data_size = (size_t)img_data_size64;
                memset(stream.stream_data + stream.stream_len, 0, img_data_size);
                stream.stream_len += img_data_size;
            }

            append_stream(&stream, endstream_marker, sizeof(endstream_marker) - 1);
        }
    }

    write(client_fd, stream.stream_data, stream.stream_len);
    free(stream.stream_data);
    return 0;
}

int main(int argc, char *argv[]) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(9090);
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) return 1;
    listen(server_fd, 5);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        char headers[MAX_HEADER_SIZE];
        ssize_t n = read(client_fd, headers, sizeof(headers) - 1);
        if (n <= 0) { close(client_fd); continue; }
        headers[n] = '\0';

        PdfConfig config;
        ImageMeta meta;

        if (validate_proxy_headers(headers, &config, &meta) == 0) {
            generate_pdf(&config, &meta, client_fd);
        }

        close(client_fd);
    }

    close(server_fd);
    return 0;
}
